package com.getrends;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("ge-trends-portfolio")
public interface GeTrendsConfig extends Config
{
	@ConfigItem(
		keyName = "cloudSync",
		name = "Cloud portfolio sync",
		description = "Send your own Grand Exchange offer updates to your private GE Trends portfolio.",
		position = 0,
		warning = "This feature submits your IP address to a 3rd-party server not controlled or verified by RuneLite developers"
	)
	default boolean cloudSync()
	{
		return false;
	}

	@ConfigItem(
		keyName = "apiToken",
		name = "Connection token",
		description = "The revocable portfolio-only token generated at ge-trends.vercel.app/account.",
		position = 1,
		secret = true
	)
	default String apiToken()
	{
		return "";
	}
}

package com.getrends;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.config.ConfigManager;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

import java.io.IOException;
import java.time.Instant;

@Slf4j
@PluginDescriptor(
	name = "GE Trends Portfolio",
	description = "Sends read-only Grand Exchange offer updates to your private GE Trends portfolio",
	tags = {"grand exchange", "investment", "portfolio", "profit"}
)
public class GeTrendsPlugin extends Plugin
{
	static final String SNAPSHOT_URL = "https://ge-trends.vercel.app/api/portfolio/snapshot";
	private static final MediaType JSON = MediaType.get("application/json; charset=utf-8");

	@Inject
	private OkHttpClient httpClient;

	@Inject
	private Gson gson;

	@Inject
	private GeTrendsConfig config;

	@Provides
	GeTrendsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GeTrendsConfig.class);
	}

	@Override
	protected void startUp()
	{
		log.info("GE Trends Portfolio tracker started");
	}

	@Override
	protected void shutDown()
	{
		// Enqueued requests are short-lived and owned by RuneLite's shared client.
		log.info("GE Trends Portfolio tracker stopped");
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (!config.cloudSync())
		{
			return;
		}

		String token = config.apiToken().trim();
		if (token.isEmpty())
		{
			log.debug("GE Trends cloud sync is enabled but the connection token is missing");
			return;
		}

		GrandExchangeOffer offer = event.getOffer();
		JsonObject snapshot = createSnapshot(
			event.getSlot(),
			offer.getItemId(),
			offer.getState().name(),
			offer.getQuantitySold(),
			offer.getSpent(),
			offer.getTotalQuantity(),
			offer.getPrice(),
			Instant.now().toString()
		);

		Request request = createRequest(token, gson.toJson(snapshot));
		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException exception)
			{
				log.debug("GE Trends is not available", exception);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response ignored = response)
				{
					if (!response.isSuccessful())
					{
						log.debug("GE Trends rejected an offer update with HTTP {}", response.code());
					}
				}
			}
		});
	}

	static JsonObject createSnapshot(
		int slot,
		int itemId,
		String state,
		int quantityFilled,
		long spent,
		int totalQuantity,
		int offerPrice,
		String observedAt)
	{
		JsonObject snapshot = new JsonObject();
		snapshot.addProperty("slot", slot);
		snapshot.addProperty("itemId", itemId);
		snapshot.addProperty("state", state);
		snapshot.addProperty("quantityFilled", quantityFilled);
		snapshot.addProperty("spent", spent);
		snapshot.addProperty("totalQuantity", totalQuantity);
		snapshot.addProperty("offerPrice", offerPrice);
		snapshot.addProperty("observedAt", observedAt);
		return snapshot;
	}

	static Request createRequest(String token, String snapshotJson)
	{
		return new Request.Builder()
			.url(SNAPSHOT_URL)
			.header("Authorization", "Bearer " + token)
			.header("Cache-Control", "no-store")
			.post(RequestBody.create(JSON, snapshotJson))
			.build();
	}
}

package com.getrends;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class GeTrendsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(GeTrendsPlugin.class);
		RuneLite.main(args);
	}
}

package com.getrends;

import com.google.gson.JsonObject;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import okhttp3.Request;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GeTrendsSecurityTest
{
	@Test
	public void snapshotContainsOnlyDocumentedOfferFields()
	{
		JsonObject snapshot = GeTrendsPlugin.createSnapshot(
			3,
			4151,
			"BUYING",
			25,
			2_500_000L,
			100,
			100_000,
			"2026-07-29T12:00:00Z"
		);

		Set<String> expected = new HashSet<>(Arrays.asList(
			"slot",
			"itemId",
			"state",
			"quantityFilled",
			"spent",
			"totalQuantity",
			"offerPrice",
			"observedAt"
		));

		assertEquals(expected, snapshot.keySet());
		assertFalse(snapshot.has("account"));
		assertFalse(snapshot.has("username"));
		assertFalse(snapshot.has("character"));
	}

	@Test
	public void requestUsesFixedHttpsEndpointAndAuthorizationHeader()
	{
		String token = "test-token-that-is-never-logged";
		Request request = GeTrendsPlugin.createRequest(token, "{}");

		assertTrue(request.url().isHttps());
		assertEquals("ge-trends.vercel.app", request.url().host());
		assertEquals("/api/portfolio/snapshot", request.url().encodedPath());
		assertEquals("Bearer " + token, request.header("Authorization"));
		assertFalse(request.url().toString().contains(token));
		assertEquals("no-store", request.header("Cache-Control"));
	}

	@Test
	public void cloudSynchronizationIsOptIn()
	{
		GeTrendsConfig config = new GeTrendsConfig()
		{
		};

		assertFalse(config.cloudSync());
		assertTrue(config.apiToken().isEmpty());
	}
}
